import asyncio

class AsyncTaskQueue:
    def __init__(self, handler, workers=2):
        self.handler = handler                    # async handler
        self._semaphore = asyncio.Semaphore(workers)
        self._tasks: set[asyncio.Task] = set()

    async def submit(self, payload):
        task = asyncio.create_task(self._deliver(payload))
        self._tasks.add(task)
        task.add_done_callback(self._tasks.discard)

    async def _deliver(self, envelope):
        async with self._semaphore:               # ① 控制并发数
            try:
                await self.handler(envelope["payload"])  # ② 异步 handler
            except PermanentTaskError as exc:
                await self._dead_letter(envelope, str(exc))
            except Exception as exc:
                if envelope["attempt"] >= self.max_attempts:
                    await self._dead_letter(envelope, str(exc))
                else:
                    delay = min(2 ** envelope["attempt"], 10)
                    await asyncio.sleep(delay)     # ③ 异步等待，不阻塞
                    envelope["attempt"] += 1
                    await self.submit(envelope["payload"])

    async def close(self):
        await asyncio.gather(*self._tasks, return_exceptions=True)
